// aphrody.com home. Audience: visitors, search engines and AI crawlers. Copy is short and comes from
// packages/i18n (keys home.*, en fr zh-CN ja es); every product row states what exists, read from
// docs/games/PLAN.md, docs/games/PARITY.md and docs/infra/PROD-MAP.md (2026-11-13). No metric is invented.
// Visuals are original and generated by code (hills, sun, tiles, the Volt pet from assets/brand/pet), coloured by
// the themes of packages/design/tokens/themes.css (dawn in light mode, ember in dark mode).
import { existsSync, readFileSync } from "node:fs";
import { extname, join } from "node:path";
import {
  FONT_LINK,
  NATIVE_CSS,
  readBrand,
  tokensCss,
  type,
} from "../../../../packages/deploy/src/m3.ts";
import { catalogs } from "../../../../packages/i18n/src/index.ts";

export const HOME_LOCALES = ["fr", "en", "zh-CN", "ja", "es"] as const;
export type HoldingLocale = (typeof HOME_LOCALES)[number];
type State = "built" | "partial" | "planned";

interface ProductBase {
  id: string;
  /** Real product art, relative to the repository root: the product's own icon (assets/library/icons/vendors) or the owner mark. */
  icon: string;
  url?: string;
  state: State;
}
/** A product with its texts in every locale (documents.ts reads name, status[l] and text[l]). */
export interface Product extends ProductBase {
  name: string;
  status: Record<HoldingLocale, string>;
  text: Record<HoldingLocale, string>;
}

/** Products that exist in the repository, with their state on 2026-11-13. */
const BASE: ProductBase[] = [
  {
    id: "play",
    icon: "assets/library/icons/vendors/bevy.png",
    url: "/play",
    state: "partial",
  },
  {
    id: "app",
    icon: "assets/brand/gen/owner/mark-512.png",
    url: "https://aphrody.app/",
    state: "built",
  },
  {
    id: "nt",
    icon: "assets/library/icons/vendors/windows.ico",
    state: "partial",
  },
  { id: "ay", icon: "assets/brand/gen/owner/mark-512.png", state: "built" },
  {
    id: "craft",
    icon: "assets/library/icons/vendors/artcraft.png",
    state: "planned",
  },
];

const COMMUNITIES = [
  { name: "Rose Griffon", url: "https://rosegriffon.fr/" },
  { name: "DBFR", url: "https://dragonballfr.com/" },
];

const OG_LOCALE: Record<HoldingLocale, string> = {
  fr: "fr_FR",
  en: "en_US",
  "zh-CN": "zh_CN",
  ja: "ja_JP",
  es: "es_ES",
};
const NATIVE_NAME: Record<HoldingLocale, string> = {
  fr: "Français",
  en: "English",
  "zh-CN": "中文",
  ja: "日本語",
  es: "Español",
};

const tr = (l: HoldingLocale, key: string): string => {
  const v = (catalogs[l] as Record<string, string>)[key];
  if (v === undefined) throw new Error(`i18n key ${key} missing in ${l}`);
  return l === "fr" ? v.replace(/ ([;:!?])/g, "\u202f$1") : v;
};
const perLocale = (f: (l: HoldingLocale) => string) =>
  Object.fromEntries(HOME_LOCALES.map((l) => [l, f(l)])) as Record<
    HoldingLocale,
    string
  >;
export const PRODUCTS: Product[] = BASE.map((p) => ({
  ...p,
  name: tr("en", `home.p.${p.id}.name`),
  status: perLocale((l) => tr(l, `home.state.${p.state}`)),
  text: perLocale((l) => tr(l, `home.p.${p.id}.text`)),
}));
const name = (p: Product) => p.name;

const esc = (s: string) =>
  s.replace(
    /[&<>"']/g,
    (c) =>
      ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[
        c
      ]!,
  );

const pagePath = (l: HoldingLocale) => (l === "fr" ? "/" : `/${l}`);
const abs = (l: HoldingLocale) => `https://aphrody.com${pagePath(l)}`;

// --- Original illustrations, generated by code ------------------------------------------------------------

const r1 = (n: number) => Math.round(n);
/** Deterministic pseudo-random sequence (LCG), so the build is reproducible. */
function rng(seed: number) {
  let s = seed >>> 0;
  return () => (s = (Math.imul(s, 1664525) + 1013904223) >>> 0) / 2 ** 32;
}

/** A hill silhouette: sum of sines, closed at the bottom of a 1440x800 scene. */
function hill(
  seed: number,
  base: number,
  amp: number,
  w = 1440,
  h = 800,
): string {
  let d = `M0 ${h}`;
  for (let x = 0; x <= w; x += 48)
    d += `L${x} ${r1(base + amp * (Math.sin(x / 230 + seed) + 0.5 * Math.sin(x / 97 + seed * 2.3)))}`;
  return `${d}L${w} ${h}Z`;
}
const hillY = (x: number, seed: number, base: number, amp: number) =>
  base + amp * (Math.sin(x / 230 + seed) + 0.5 * Math.sin(x / 97 + seed * 2.3));

function pines(
  seed: number,
  hillSeed: number,
  base: number,
  amp: number,
  n: number,
): string {
  const rand = rng(seed);
  let out = "";
  for (let i = 0; i < n; i++) {
    const x = r1(40 + rand() * 1360);
    const y = r1(hillY(x, hillSeed, base, amp) + 6);
    const s = 0.7 + rand() * 0.9;
    const h = 46 * s;
    const w = 15 * s;
    out += `M${r1(x - w)} ${y}L${x} ${r1(y - h)}L${r1(x + w)} ${y}Z`;
  }
  return `<path fill="var(--pine)" d="${out}"/>`;
}

/** Volt, the Aphrody pet: assets/brand/pet/pet.svg painted with the theme roles (original artwork). */
function pet(root: string): string {
  const f = join(root, "assets", "brand", "pet", "pet.svg");
  if (!existsSync(f)) return "";
  const body = readFileSync(f, "utf8")
    .replace(/<!--[\s\S]*?-->/g, "")
    .replace(/^[\s\S]*?<svg[^>]*>/, "")
    .replace(/<\/svg>\s*$/, "");
  const map: Record<string, string> = {
    body: "var(--pet-body)",
    body_dark: "var(--pet-dark)",
    face: "#1d1a2b",
    eye: "#FFB300",
    bolt: "#FFB300",
    mouth: "M42 59Q48 63 54 59",
    extras: "",
    style: "",
    state: "idle",
    root_t: "",
    arm_l_t: "",
    arm_r_t: "",
    eyes_t: "",
    bolt_op: "1",
  };
  return body.replace(/\{(\w+)\}/g, (_, k: string) => map[k] ?? "");
}

/** Sprite /art.svg: every illustration as a <g id>, referenced by <use> from the page. Shapes take their colours from
 * custom properties (inherited through <use>), so the page stylesheet themes them and the HTML stays small. */
export function artSprite(root: string): string {
  const rand = rng(7);
  let stars = "";
  for (let i = 0; i < 32; i++)
    stars += `<circle cx="${r1(rand() * 1440)}" cy="${r1(rand() * 420)}" r="${r1(0.8 + rand() * 1.6)}"/>`;
  const g = (id: string, body: string) => `<g id="${id}">${body}</g>`;
  return `<svg xmlns="http://www.w3.org/2000/svg"><defs><radialGradient id="glow"><stop offset="0" stop-color="#FFB300" stop-opacity=".55"/><stop offset="1" stop-color="#FFB300" stop-opacity="0"/></radialGradient></defs>${[
    g("stars", `<g fill="var(--star)">${stars}</g>`),
    g(
      "sun",
      `<circle cx="1040" cy="330" r="300" fill="url(#glow)"/><circle cx="1040" cy="330" r="104" fill="#FFB300"/><g fill="none" stroke="#FFB300" stroke-opacity=".28" stroke-width="2"><circle cx="1040" cy="330" r="150"/><circle cx="1040" cy="330" r="214"/></g>`,
    ),
    g("h1", `<path fill="var(--h1)" d="${hill(1.1, 520, 40)}"/>`),
    g(
      "h2",
      `<path fill="var(--h2)" d="${hill(2.4, 580, 46)}"/>${pines(3, 2.4, 580, 46, 8)}`,
    ),
    g(
      "h3",
      `<path fill="var(--h3)" d="${hill(4.7, 650, 38)}"/>${pines(9, 4.7, 650, 38, 7)}`,
    ),
    g("h4", `<path fill="var(--h4)" d="${hill(6.2, 730, 24)}"/>`),
    g("volt", pet(root)),
  ].join("")}</svg>`;
}

const use = (id: string, cls = "") =>
  `<use${cls ? ` class="${cls}"` : ""} href="/art.svg#${id}"/>`;

function heroScene(alt: string): string {
  return `<div class="scene" role="img" aria-label="${esc(alt)}"><svg width="1440" height="800" viewBox="0 0 1440 800" preserveAspectRatio="xMidYMax slice" aria-hidden="true">${use("stars", "stars")}${use("sun")}${use("h1", "par p1")}${use("h2", "par p2")}${use("h3", "par p3")}${use("h4")}${use("volt", "volt")}</svg></div>`;
}

/** Public path of a product's own icon (emitted by build.ts from `icon`). */
const iconPath = (p: ProductBase) => `/icons/${p.id}${extname(p.icon)}`;
const art = (p: ProductBase, alt: string) =>
  `<img class="pico" src="${iconPath(p)}" alt="${esc(alt)}" width="72" height="72" loading="lazy">`;

// --- Page ---------------------------------------------------------------------------------------------

const stateLabel = (s: State, l: HoldingLocale) => tr(l, `home.state.${s}`);

/** JSON-LD graph: Organization, WebSite and the product list, for search engines and AI crawlers. */
export function holdingJsonLd(l: HoldingLocale): Record<string, unknown> {
  return {
    "@context": "https://schema.org",
    "@graph": [
      {
        "@type": "Organization",
        "@id": "https://aphrody.com/#org",
        name: "Aphrody",
        url: "https://aphrody.com/",
        logo: "https://aphrody.com/icon-512.png",
        email: "contact@aphrody.com",
        description: tr(l, "home.desc"),
      },
      {
        "@type": "WebSite",
        "@id": "https://aphrody.com/#site",
        url: "https://aphrody.com/",
        name: "Aphrody",
        inLanguage: l,
        publisher: { "@id": "https://aphrody.com/#org" },
      },
      {
        "@type": "ItemList",
        name: tr(l, "home.apps"),
        itemListElement: PRODUCTS.map((p, i) => ({
          "@type": "ListItem",
          position: i + 1,
          item: {
            "@type": "SoftwareApplication",
            name: name(p),
            description: tr(l, `home.p.${p.id}.text`),
            applicationCategory: "DeveloperApplication",
            image: `https://aphrody.com${iconPath(p)}`,
            ...(p.url
              ? {
                  url: p.url.startsWith("/")
                    ? `https://aphrody.com${p.url}`
                    : p.url,
                }
              : {}),
            provider: { "@id": "https://aphrody.com/#org" },
          },
        })),
      },
    ],
  };
}

export function renderHolding(root: string, l: HoldingLocale): string {
  const brand = readBrand(root);
  const t = (k: string) => tr(l, k);
  const cards = PRODUCTS.map(
    (p) =>
      `<li class="card c-${p.id}"><div class="head">${art(p, name(p))}<div><h3>${esc(name(p))}</h3><span class="status s-${p.state}">${esc(stateLabel(p.state, l))}</span></div></div><p>${esc(t(`home.p.${p.id}.text`))}</p>${p.url ? `<md-outlined-button class="open" href="${p.url}" aria-label="${esc(t("home.open"))} ${esc(name(p))}">${esc(t("home.open"))}</md-outlined-button>` : ""}</li>`,
  ).join("");
  const langs = HOME_LOCALES.map(
    (x) =>
      `<a href="${pagePath(x)}" hreflang="${x}" lang="${x}"${x === l ? ' aria-current="page"' : ""}>${NATIVE_NAME[x]}</a>`,
  ).join("");
  const alternates =
    HOME_LOCALES.map(
      (x) => `<link rel="alternate" hreflang="${x}" href="${abs(x)}">`,
    ).join("") +
    `<link rel="alternate" hreflang="x-default" href="https://aphrody.com/">`;
  const head = `<meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${esc(t("home.title"))}</title><meta name="description" content="${esc(t("home.desc"))}"><meta name="color-scheme" content="light dark"><link rel="canonical" href="${abs(l)}">${alternates}<link rel="icon" href="/favicon.ico" sizes="32x32"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="manifest" href="/site.webmanifest"><link rel="apple-touch-icon" href="/apple-touch-icon.png"><meta property="og:type" content="website"><meta property="og:site_name" content="Aphrody"><meta property="og:title" content="${esc(t("home.title"))}"><meta property="og:description" content="${esc(t("home.desc"))}"><meta property="og:url" content="${abs(l)}"><meta property="og:image" content="https://aphrody.com/og-image.png"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="Aphrody"><meta property="og:locale" content="${OG_LOCALE[l]}"><meta name="twitter:card" content="summary_large_image"><meta name="robots" content="index, follow, max-snippet:-1, max-image-preview:large, max-video-preview:-1"><script>document.documentElement.dataset.theme=matchMedia("(prefers-color-scheme:dark)").matches?"ember":"dawn"</script>${FONT_LINK}<link rel="stylesheet" href="/holding.css"><script type="module" src="/md.js"></script><script src="/_aphrody/insights.js" defer></script><script type="application/ld+json">${JSON.stringify(holdingJsonLd(l)).replace(/</g, "\\u003c")}</script>`;
  const community = COMMUNITIES.map(
    (c) => `<a href="${c.url}">${c.name}</a>`,
  ).join(", ");
  return `<!doctype html><html lang="${l}"><head>${head}</head><body><a class="skip" href="#main">${t("home.skip")}</a><header class="bar"><a class="brand" href="${pagePath(l)}">${brand.mark}<span>Aphrody</span></a><nav class="langs" aria-label="${esc(t("home.lang"))}">${langs}</nav></header><main id="main"><section class="hero">${heroScene(t("home.alt"))}<div class="wrap"><h1>Aphrody</h1><p class="lead">${esc(t("app.tagline"))}</p><div class="actions"><md-filled-button href="/play">Play</md-filled-button><md-outlined-button href="https://aphrody.app/">aphrody.app</md-outlined-button></div></div></section><section class="block products" aria-labelledby="apps"><div class="wrap"><h2 id="apps">${t("home.apps")}</h2><ul role="list">${cards}</ul></div></section></main><footer><div class="wrap"><p>${esc(t("home.communities"))} ${community}.</p><p><a href="mailto:contact@aphrody.com">contact@aphrody.com</a></p><p>Aphrody, 2026</p></div></footer><script type="module" src="/stage-home.js"></script></body></html>`;
}

/** Real product art to publish: repository file and its path in dist (icons/<id>.<ext>). */
export function productIcons(root: string): { file: string; out: string }[] {
  return PRODUCTS.map((p) => ({
    file: join(root, p.icon),
    out: iconPath(p).slice(1),
  })).filter((x) => existsSync(x.file));
}

/** 404 page: same shell and stylesheet, short message, links back home. */
export function holding404(root: string): string {
  const brand = readBrand(root);
  return `<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Page introuvable, Aphrody</title><meta name="robots" content="noindex"><meta name="color-scheme" content="light dark"><link rel="icon" href="/favicon.ico" sizes="32x32"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><script>document.documentElement.dataset.theme=matchMedia("(prefers-color-scheme:dark)").matches?"ember":"dawn"</script>${FONT_LINK}<link rel="stylesheet" href="/holding.css"></head><body><header class="bar"><a class="brand" href="/">${brand.mark}<span>Aphrody</span></a></header><main id="main"><section class="block"><div class="wrap"><h1>Page introuvable</h1><p class="lead">Cette adresse n'existe pas ou plus.</p><p><a href="/">Revenir à l'accueil</a> · <a href="/en" lang="en" hreflang="en">Back to the home page</a></p></div></section></main></body></html>`;
}

// Themes dawn (light) and ember (dark) from packages/design/tokens/themes.css: the plain blocks only.
function themeBlocks(root: string): string {
  const f = join(root, "packages", "design", "tokens", "themes.css");
  const css = readFileSync(f, "utf8").replace(/\/\*[\s\S]*?\*\//g, "");
  return [...css.matchAll(/:root\[data-theme="(?:dawn|ember)"\]\s*\{[^}]*\}/g)]
    .map((m) => m[0])
    .join("\n");
}

